  IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('p02_dashboard_authorization_context_v1','p02_lock_dashboard_principals_v1','p02_lock_membership_v1','p02_update_membership_v1','p02_dashboard_subject_context_v1','p04_append_audit_event_v1','p04_audit_list_v1','p04_audit_detail_v1','p10_has_anonymous_analytics_consent_v1'))<>9 THEN RAISE EXCEPTION 'M72_OVERLOAD_ASSERT'; END IF;
  IF has_table_privilege('vanstro_runtime','public.users','SELECT') OR has_table_privilege('vanstro_runtime','public.dealer_memberships','SELECT') OR has_table_privilege('vanstro_runtime','public.audit_events','SELECT') OR has_table_privilege('vanstro_runtime','public.audit_events','INSERT') OR has_table_privilege('vanstro_runtime','public.audit_events','UPDATE') OR has_table_privilege('vanstro_runtime','public.audit_events','DELETE') THEN RAISE EXCEPTION 'M72_DIRECT_TABLE_ASSERT'; END IF;
  IF NOT has_function_privilege('vanstro_runtime','public.p02_dashboard_authorization_context_v1(text,text)','EXECUTE') OR NOT has_function_privilege('vanstro_runtime','public.p04_append_audit_event_v1(text,text,jsonb)','EXECUTE') OR NOT has_function_privilege('vanstro_runtime','public.p04_audit_detail_v1(text,text,uuid,timestamptz)','EXECUTE') THEN RAISE EXCEPTION 'M72_EXECUTE_ASSERT'; END IF;
END $assert$;

