CREATE FUNCTION public.p05_api_create_probe_v1(session_token_hash text,expected_actor_id text,job jsonb,idempotency_candidates text[],event_intent_hash text)
RETURNS TABLE(job_id uuid,replayed boolean) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;g jsonb;j public.async_jobs%ROWTYPE;existing public.async_jobs%ROWTYPE;
BEGIN
 context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='jobs.create');
 IF g IS NULL THEN RAISE EXCEPTION 'P05_CREATE_DENIED' USING ERRCODE='42501';END IF;
 j:=jsonb_populate_record(NULL::public.async_jobs,job);j.version:=COALESCE(j.version,0);j."createdAt":=COALESCE(j."createdAt",CURRENT_TIMESTAMP);j."updatedAt":=COALESCE(j."updatedAt",CURRENT_TIMESTAMP);j."bindingRevision":=COALESCE(j."bindingRevision",0);j.attempt:=COALESCE(j.attempt,0);j."generationAttempt":=COALESCE(j."generationAttempt",0);j."retryGeneration":=COALESCE(j."retryGeneration",0);j."leaseRevision":=COALESCE(j."leaseRevision",0);j."processedCount":=COALESCE(j."processedCount",0);j."failedCount":=COALESCE(j."failedCount",0);
 IF j."jobType"<>'foundation.probe' OR j.status<>'queued' OR j."createdByActorType"<>'admin_user' OR j."createdByActorId"<>expected_actor_id OR j."contextRevision"<>context->>'contextRevision' OR j."eventIntentHash"<>event_intent_hash OR j."leaseOwner" IS NOT NULL OR NOT ((g->>'global')::boolean AND j."authorizationScopeKind"='global' OR NOT (g->>'global')::boolean AND j."authorizationScopeKind" IN('dealer','location') AND j."dealerIds"=g->'dealerIds' AND j."locationIds"=g->'locationIds') THEN RAISE EXCEPTION 'P05_CREATE_INVALID';END IF;
 SELECT * INTO existing FROM public.async_jobs WHERE "jobType"=j."jobType" AND "idempotencyKeyHash"=ANY(idempotency_candidates) FOR UPDATE;
 IF FOUND THEN IF existing."eventIntentHash"<>event_intent_hash THEN RAISE EXCEPTION 'P05_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';END IF;RETURN QUERY SELECT existing.id,true;RETURN;END IF;
 INSERT INTO public.async_jobs SELECT j.* RETURNING * INTO j;RETURN QUERY SELECT j.id,false;
END $fn$;

CREATE FUNCTION public.p05_api_list_v1(session_token_hash text,expected_actor_id text,scope_kind text,dealer_ids text[],location_ids text[],created_from timestamptz,created_to timestamptz,limit_rows integer,after_created_at timestamptz,after_id uuid,status_filter text[],job_type_filter text[],actor_filter text,cancellable_filter boolean,retryable_filter boolean)
RETURNS SETOF public.async_jobs LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;g jsonb;
BEGIN context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='jobs.read');IF g IS NULL OR limit_rows NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION 'P05_READ_DENIED' USING ERRCODE='42501';END IF;
 IF scope_kind<>(CASE WHEN (g->>'global')::boolean THEN 'global' WHEN jsonb_array_length(g->'locationIds')>0 THEN 'location' ELSE 'dealer' END) OR dealer_ids<>ARRAY(SELECT value FROM jsonb_array_elements_text(g->'dealerIds') value ORDER BY value) OR location_ids<>ARRAY(SELECT value FROM jsonb_array_elements_text(g->'locationIds') value ORDER BY value) THEN RAISE EXCEPTION 'P05_SCOPE_MISMATCH' USING ERRCODE='42501';END IF;
 RETURN QUERY SELECT j.* FROM public.async_jobs j WHERE j."createdAt">=created_from AND j."createdAt"<created_to AND ((g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'dealerIds') gd WHERE j."dealerIds" ? gd) AND (j."authorizationScopeKind"='dealer' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'locationIds') gl WHERE j."locationIds" ? gl)))) AND (cardinality(status_filter)=0 OR j.status=ANY(status_filter)) AND (cardinality(job_type_filter)=0 OR j."jobType"=ANY(job_type_filter)) AND (actor_filter IS NULL OR j."createdByActorType"=actor_filter) AND (cancellable_filter IS NULL OR cancellable_filter=(j.status IN('queued','running'))) AND (retryable_filter IS NULL OR retryable_filter=(j.status='failed' AND j."retryGeneration"<j."maxRetryGenerations")) AND (after_created_at IS NULL OR (j."createdAt",j.id)<(after_created_at,after_id)) ORDER BY j."createdAt" DESC,j.id DESC LIMIT limit_rows;
END $fn$;

CREATE FUNCTION public.p05_api_detail_v1(session_token_hash text,expected_actor_id text,job_id uuid)
RETURNS SETOF public.async_jobs LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;g jsonb;BEGIN context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='jobs.read');IF g IS NULL THEN RETURN;END IF;RETURN QUERY SELECT j.* FROM public.async_jobs j WHERE j.id=job_id AND ((g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'dealerIds') d WHERE j."dealerIds" ? d) AND (j."authorizationScopeKind"='dealer' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'locationIds') l WHERE j."locationIds" ? l))));END $fn$;

CREATE FUNCTION public.p05_api_artifacts_v1(session_token_hash text,expected_actor_id text,job_id uuid)
RETURNS SETOF public.job_artifacts LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
BEGIN IF NOT EXISTS(SELECT 1 FROM public.p05_api_detail_v1(session_token_hash,expected_actor_id,job_id)) THEN RETURN;END IF;RETURN QUERY SELECT a.* FROM public.job_artifacts a WHERE a."jobId"=job_id ORDER BY a."createdAt",a.id;END $fn$;

CREATE FUNCTION public.p05_api_cancel_v1(session_token_hash text,expected_actor_id text,job_id uuid,expected_version integer)
RETURNS SETOF public.async_jobs LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;j public.async_jobs%ROWTYPE;g jsonb;BEGIN context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='jobs.cancel');IF g IS NULL THEN RAISE EXCEPTION 'P05_CANCEL_DENIED' USING ERRCODE='42501';END IF;SELECT * INTO j FROM public.async_jobs WHERE id=job_id FOR UPDATE;IF NOT FOUND OR NOT ((g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'dealerIds') d WHERE j."dealerIds" ? d) AND (j."authorizationScopeKind"='dealer' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'locationIds') l WHERE j."locationIds" ? l)))) OR j.version<>expected_version OR j.status NOT IN('queued','running') OR j."jobType"<>'foundation.probe' THEN RAISE EXCEPTION 'P05_STATE_CONFLICT';END IF;UPDATE public.async_jobs SET status=CASE WHEN status='queued' THEN 'cancelled' ELSE status END,"cancellationRequestedAt"=CURRENT_TIMESTAMP,"cancellationRequestedBy"=expected_actor_id,"cancellationReason"='operator_requested',"cancelledAt"=CASE WHEN status='queued' THEN CURRENT_TIMESTAMP ELSE "cancelledAt" END,"finishedAt"=CASE WHEN status='queued' THEN CURRENT_TIMESTAMP ELSE "finishedAt" END,version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=job_id RETURNING * INTO j;RETURN NEXT j;END $fn$;

CREATE FUNCTION public.p05_api_retry_v1(session_token_hash text,expected_actor_id text,job_id uuid,expected_version integer)
RETURNS SETOF public.async_jobs LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;g jsonb;j public.async_jobs%ROWTYPE;
BEGIN context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='jobs.retry');IF g IS NULL THEN RAISE EXCEPTION 'JOB_NOT_RETRYABLE';END IF;SELECT * INTO j FROM public.async_jobs WHERE id=job_id FOR UPDATE;IF NOT FOUND OR j."jobType"<>'foundation.probe' OR j.status<>'failed' OR j.version<>expected_version OR j."retryGeneration">=j."maxRetryGenerations" OR NOT ((g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'dealerIds') d WHERE j."dealerIds" ? d) AND (j."authorizationScopeKind"='dealer' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'locationIds') l WHERE j."locationIds" ? l)))) THEN RAISE EXCEPTION 'JOB_NOT_RETRYABLE';END IF;UPDATE public.async_jobs SET status='queued',"retryGeneration"="retryGeneration"+1,"generationAttempt"=0,"nextRetryAt"=NULL,"finishedAt"=NULL,"failureClass"=NULL,"errorSummary"=NULL,version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=job_id RETURNING * INTO j;RETURN NEXT j;END $fn$;

CREATE FUNCTION public.p06_api_mutate_item_v1(session_token_hash text,expected_actor_id text,item_id uuid,expected_version integer,operation text,reason text,target_user_id text,deduplication_candidates text[])
RETURNS SETOF public.work_queue_items LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;permission_key text;g jsonb;source_g jsonb;subject jsonb;subject_access jsonb;subject_read jsonb;subject_source jsonb;j public.work_queue_items%ROWTYPE;now_at timestamptz:=CURRENT_TIMESTAMP;clear_assignee boolean:=false;
BEGIN
 IF operation NOT IN('assign','unassign','acknowledge','resolve','dismiss','reopen') THEN RAISE EXCEPTION 'WORK_ITEM_STATE_CONFLICT';END IF;
 permission_key:=CASE WHEN operation IN('assign','unassign') THEN 'work_queue.assign' ELSE 'work_queue.'||operation END;
 context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);
 g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'=permission_key);
 SELECT * INTO j FROM public.work_queue_items WHERE id=item_id FOR UPDATE;
 IF NOT FOUND OR g IS NULL THEN RAISE EXCEPTION 'WORK_ITEM_SCOPE_CHANGED' USING ERRCODE='42501';END IF;
 source_g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'=j."sourcePermission");
 IF source_g IS NULL OR NOT ((g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."dealerIds") d WHERE NOT (g->'dealerIds' ? d)) AND (j."authorizationScopeKind"='dealer' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."locationIds") l WHERE NOT (g->'locationIds' ? l))))) OR NOT ((source_g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."dealerIds") d WHERE NOT (source_g->'dealerIds' ? d)) AND (j."authorizationScopeKind"='dealer' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."locationIds") l WHERE NOT (source_g->'locationIds' ? l))))) THEN RAISE EXCEPTION 'WORK_ITEM_SCOPE_CHANGED' USING ERRCODE='42501';END IF;
 IF j.version<>expected_version THEN RAISE EXCEPTION 'WORK_ITEM_STATE_CONFLICT';END IF;
 IF operation IN('assign','unassign') THEN
  IF j.status NOT IN('open','acknowledged') OR (operation='assign' AND target_user_id IS NULL) OR (operation='unassign' AND target_user_id IS NOT NULL) THEN RAISE EXCEPTION 'WORK_ITEM_NOT_ACTIONABLE';END IF;
  IF target_user_id IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM public.users u WHERE u.id=target_user_id AND u.kind='admin' AND u.status='active') THEN RAISE EXCEPTION 'WORK_ITEM_ASSIGNEE_INVALID';END IF;
   subject:=public.p02_dashboard_subject_context_v1(session_token_hash,expected_actor_id,target_user_id::text);
   subject_access:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='dashboard.access');subject_read:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='work_queue.read');subject_source:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'=j."sourcePermission");
   IF subject_access IS NULL OR subject_read IS NULL OR subject_source IS NULL OR NOT ((subject_read->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."dealerIds") d WHERE NOT (subject_read->'dealerIds' ? d)) AND (j."authorizationScopeKind"='dealer' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."locationIds") l WHERE NOT (subject_read->'locationIds' ? l))))) OR NOT ((subject_source->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."dealerIds") d WHERE NOT (subject_source->'dealerIds' ? d)) AND (j."authorizationScopeKind"='dealer' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."locationIds") l WHERE NOT (subject_source->'locationIds' ? l))))) THEN RAISE EXCEPTION 'WORK_ITEM_ASSIGNEE_INVALID';END IF;
  END IF;
  UPDATE public.work_queue_items SET "assignedToUserId"=target_user_id,"assignedAt"=CASE WHEN target_user_id IS NULL THEN NULL ELSE now_at END,"assignedByActorType"=CASE WHEN target_user_id IS NULL THEN NULL ELSE 'admin_user' END,"assignedByActorId"=CASE WHEN target_user_id IS NULL THEN NULL ELSE expected_actor_id END,version=version+1,"updatedAt"=now_at WHERE id=item_id RETURNING * INTO j;
 ELSIF operation='acknowledge' THEN
  IF reason IS NOT NULL AND reason<>'operator_acknowledged' OR j.health='orphaned' OR j.status<>'open' THEN RAISE EXCEPTION 'WORK_ITEM_STATE_CONFLICT';END IF;
  UPDATE public.work_queue_items SET status='acknowledged',"acknowledgedAt"=now_at,"acknowledgedByActorType"='admin_user',"acknowledgedByActorId"=expected_actor_id,"lastTransitionReason"=COALESCE(reason,'operator_acknowledged'),version=version+1,"updatedAt"=now_at WHERE id=item_id RETURNING * INTO j;
 ELSIF operation IN('resolve','dismiss') THEN
  IF reason<>(CASE WHEN operation='resolve' THEN 'operator_resolved' ELSE 'not_actionable' END) OR j.status NOT IN('open','acknowledged') OR (operation='resolve' AND j.health='orphaned') THEN RAISE EXCEPTION 'WORK_ITEM_STATE_CONFLICT';END IF;
  IF operation='resolve' THEN UPDATE public.work_queue_items SET status='resolved',"acknowledgedAt"=NULL,"acknowledgedByActorType"=NULL,"acknowledgedByActorId"=NULL,"resolvedAt"=now_at,"resolvedByActorType"='admin_user',"resolvedByActorId"=expected_actor_id,"resolutionReason"=reason,"retentionExpiresAt"=now_at+interval '180 days',"lastTransitionReason"=reason,version=version+1,"updatedAt"=now_at WHERE id=item_id RETURNING * INTO j;
  ELSE UPDATE public.work_queue_items SET status='dismissed',"acknowledgedAt"=NULL,"acknowledgedByActorType"=NULL,"acknowledgedByActorId"=NULL,"dismissedAt"=now_at,"dismissedByActorType"='admin_user',"dismissedByActorId"=expected_actor_id,"dismissalReason"=reason,"retentionExpiresAt"=now_at+interval '180 days',"lastTransitionReason"=reason,version=version+1,"updatedAt"=now_at WHERE id=item_id RETURNING * INTO j;END IF;
 ELSE
  IF reason<>'operator_correction' OR j.health='orphaned' OR j.status NOT IN('resolved','dismissed') OR cardinality(deduplication_candidates)=0 OR EXISTS(SELECT 1 FROM public.work_queue_items newer WHERE newer.type=j.type AND newer."deduplicationKeyHash"=ANY(deduplication_candidates) AND newer.id<>j.id AND (newer.status IN('open','acknowledged') OR newer.occurrence>j.occurrence)) THEN RAISE EXCEPTION 'WORK_ITEM_STATE_CONFLICT';END IF;
  IF j."assignedToUserId" IS NOT NULL THEN BEGIN subject:=public.p02_dashboard_subject_context_v1(session_token_hash,expected_actor_id,j."assignedToUserId"::text);subject_access:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='dashboard.access');subject_read:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='work_queue.read');subject_source:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'=j."sourcePermission");clear_assignee:=subject_access IS NULL OR subject_read IS NULL OR subject_source IS NULL;EXCEPTION WHEN OTHERS THEN clear_assignee:=true;END;END IF;
  UPDATE public.work_queue_items SET status='open',"assignedToUserId"=CASE WHEN clear_assignee THEN NULL ELSE "assignedToUserId" END,"assignedAt"=CASE WHEN clear_assignee THEN NULL ELSE "assignedAt" END,"assignedByActorType"=CASE WHEN clear_assignee THEN NULL ELSE "assignedByActorType" END,"assignedByActorId"=CASE WHEN clear_assignee THEN NULL ELSE "assignedByActorId" END,"resolvedAt"=NULL,"resolvedByActorType"=NULL,"resolvedByActorId"=NULL,"resolutionReason"=NULL,"dismissedAt"=NULL,"dismissedByActorType"=NULL,"dismissedByActorId"=NULL,"dismissalReason"=NULL,"acknowledgedAt"=NULL,"acknowledgedByActorType"=NULL,"acknowledgedByActorId"=NULL,"retentionExpiresAt"=NULL,"lastTransitionReason"=reason,version=version+1,"updatedAt"=now_at WHERE id=item_id RETURNING * INTO j;
 END IF;
 RETURN NEXT j;
END $fn$;

CREATE FUNCTION public.p06_api_create_notification_v1(session_token_hash text,expected_actor_id text,recipient_user_id text,item_id uuid,notification_type text,transition_version integer,deduplication_kid text,deduplication_hash text,deduplication_candidates text[])
RETURNS SETOF public.in_app_notifications LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE j public.work_queue_items%ROWTYPE;n public.in_app_notifications%ROWTYPE;subject jsonb;access_g jsonb;read_g jsonb;notify_g jsonb;source_g jsonb;now_at timestamptz:=CURRENT_TIMESTAMP;
BEGIN
 IF notification_type NOT IN('foundation.attention.assigned','foundation.attention.critical','foundation.attention.terminal','media.processing.failed') OR cardinality(deduplication_candidates)=0 OR NOT (deduplication_hash=ANY(deduplication_candidates)) THEN RAISE EXCEPTION 'NOTIFICATION_SCOPE_CHANGED';END IF;
 PERFORM public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);SELECT * INTO j FROM public.work_queue_items WHERE id=item_id FOR SHARE;IF NOT FOUND OR j.version<>transition_version THEN RAISE EXCEPTION 'NOTIFICATION_SCOPE_CHANGED';END IF;
 subject:=public.p02_dashboard_subject_context_v1(session_token_hash,expected_actor_id,recipient_user_id);access_g:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='dashboard.access');read_g:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='work_queue.read');notify_g:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'='notifications.read');source_g:=(SELECT value FROM jsonb_array_elements(subject->'permissionGrants') value WHERE value->>'permissionKey'=j."sourcePermission");IF access_g IS NULL OR read_g IS NULL OR notify_g IS NULL OR source_g IS NULL THEN RAISE EXCEPTION 'NOTIFICATION_SCOPE_CHANGED';END IF;
 SELECT * INTO n FROM public.in_app_notifications WHERE "recipientUserId"=recipient_user_id AND type=notification_type AND "deduplicationKeyHash"=ANY(deduplication_candidates);IF FOUND THEN RETURN NEXT n;RETURN;END IF;
 INSERT INTO public.in_app_notifications(id,"contractVersion",type,"typeVersion","recipientUserId","workItemId",severity,"titleKey","messageKey","safeMessageArgs","resourceType","resourceId","deepLink","authorizationScopeKind","dealerIds","locationIds","deduplicationKeyKid","deduplicationKeyHash","expiresAt",version,"createdAt") VALUES(gen_random_uuid(),'in-app-notification.v1',notification_type,notification_type||'.v1',recipient_user_id,item_id,j.severity,'work_queue_transition','work_queue_transition',jsonb_build_object('status',j.status),j."resourceType",j."resourceId",j."deepLink",j."authorizationScopeKind",j."dealerIds",j."locationIds",deduplication_kid,deduplication_hash,LEAST(now_at+interval '30 days',COALESCE(j."retentionExpiresAt",now_at+interval '30 days')),0,now_at) RETURNING * INTO n;RETURN NEXT n;
END $fn$;

CREATE FUNCTION public.p06_api_get_source_state_v1(adapter_key text,adapter_version text)
RETURNS SETOF public.work_queue_source_states LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$ SELECT * FROM public.work_queue_source_states WHERE "adapterKey"=adapter_key AND "adapterVersion"=adapter_version $fn$;

CREATE FUNCTION public.p06_api_update_source_state_v1(adapter_key text,adapter_version text,next_health text,safe_error_code text)
RETURNS SETOF public.work_queue_source_states LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE s public.work_queue_source_states%ROWTYPE;now_at timestamptz:=CURRENT_TIMESTAMP;
BEGIN IF adapter_key NOT IN('runtime_alerts','email_delivery','erp_sync','payment_reconciliation','refund_attention','low_inventory','dealer_applications','contact_leads','product_reviews','support_handoffs','async_jobs','readiness','worker_heartbeat','content_readiness') OR adapter_version<>'v1' OR next_health NOT IN('ready','stale','unavailable') OR safe_error_code IS NOT NULL AND safe_error_code!~'^[A-Z][A-Z0-9_]{0,63}$' THEN RAISE EXCEPTION 'WORK_QUEUE_SOURCE_INVALID';END IF;
 SELECT * INTO s FROM public.work_queue_source_states WHERE "adapterKey"=adapter_key AND "adapterVersion"=adapter_version FOR UPDATE;IF FOUND AND s.health=next_health AND s."safeErrorCode" IS NOT DISTINCT FROM safe_error_code THEN RETURN;END IF;
 IF FOUND THEN UPDATE public.work_queue_source_states SET health=next_health,"capturedAt"=now_at,"lastSuccessAt"=CASE WHEN next_health='ready' THEN now_at ELSE "lastSuccessAt" END,"lastFailureAt"=CASE WHEN next_health='unavailable' THEN now_at ELSE "lastFailureAt" END,"safeErrorCode"=safe_error_code,revision=revision+1,"updatedAt"=now_at WHERE id=s.id RETURNING * INTO s;
 ELSE INSERT INTO public.work_queue_source_states(id,"adapterKey","adapterVersion",health,"lastSuccessAt","lastFailureAt","safeErrorCode","capturedAt",revision,"updatedAt") VALUES(gen_random_uuid(),adapter_key,adapter_version,next_health,CASE WHEN next_health='ready' THEN now_at END,CASE WHEN next_health='unavailable' THEN now_at END,safe_error_code,now_at,0,now_at) RETURNING * INTO s;END IF;RETURN NEXT s;END $fn$;

CREATE FUNCTION public.p07_api_create_media_job_v1(session_token_hash text,expected_actor_id text,job jsonb,idempotency_candidates text[],event_intent_hash text)
RETURNS TABLE(job_id uuid,replayed boolean) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;g jsonb;j public.async_jobs%ROWTYPE;existing public.async_jobs%ROWTYPE;asset public.media_assets%ROWTYPE;
BEGIN context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='media.create');IF g IS NULL THEN RAISE EXCEPTION 'P07_CREATE_DENIED' USING ERRCODE='42501';END IF;
 j:=jsonb_populate_record(NULL::public.async_jobs,job);j.version:=COALESCE(j.version,0);j."createdAt":=COALESCE(j."createdAt",CURRENT_TIMESTAMP);j."updatedAt":=COALESCE(j."updatedAt",CURRENT_TIMESTAMP);j."bindingRevision":=COALESCE(j."bindingRevision",0);j.attempt:=COALESCE(j.attempt,0);j."generationAttempt":=COALESCE(j."generationAttempt",0);j."retryGeneration":=COALESCE(j."retryGeneration",0);j."leaseRevision":=COALESCE(j."leaseRevision",0);j."processedCount":=COALESCE(j."processedCount",0);j."failedCount":=COALESCE(j."failedCount",0);
 IF j."jobType"<>'media.process' OR j.status<>'queued' OR j."createdByActorType"<>'system' OR j."contextRevision"<>context->>'contextRevision' OR j."eventIntentHash"<>event_intent_hash OR j."leaseOwner" IS NOT NULL OR NOT (j.payload ? 'assetId') THEN RAISE EXCEPTION 'P07_CREATE_INVALID';END IF;
 SELECT * INTO asset FROM public.media_assets WHERE id=(j.payload->>'assetId')::uuid FOR SHARE;IF NOT FOUND OR asset.status<>'processing' OR asset."contextRevision"<>j."contextRevision" OR asset."authorizationScopeKind"<>j."authorizationScopeKind" OR asset."dealerIds"<>j."dealerIds" OR asset."locationIds"<>j."locationIds" OR NOT ((g->>'global')::boolean OR (asset."authorizationScopeKind" IN('dealer','location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(asset."dealerIds") d WHERE NOT (g->'dealerIds' ? d)) AND (asset."authorizationScopeKind"='dealer' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(asset."locationIds") l WHERE NOT (g->'locationIds' ? l))))) THEN RAISE EXCEPTION 'P07_CREATE_INVALID';END IF;
 SELECT * INTO existing FROM public.async_jobs e WHERE e."jobType"='media.process' AND e."idempotencyKeyHash"=ANY(idempotency_candidates) FOR UPDATE;IF FOUND THEN IF existing."eventIntentHash"<>event_intent_hash THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';END IF;RETURN QUERY SELECT existing.id,true;RETURN;END IF;
 INSERT INTO public.async_jobs SELECT j.*;RETURN QUERY SELECT j.id,false;END $fn$;

CREATE FUNCTION public.p07_api_media_job_detail_v1(session_token_hash text,expected_actor_id text,asset_id uuid,job_id uuid,required_permission text)
RETURNS SETOF public.async_jobs LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;g jsonb;BEGIN IF required_permission NOT IN('media.read','media.manage_variants','media.create') THEN RETURN;END IF;context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'=required_permission);IF g IS NULL THEN RETURN;END IF;RETURN QUERY SELECT j.* FROM public.async_jobs j WHERE j.id=job_id AND j."jobType"='media.process' AND j.payload->>'assetId'=asset_id::text AND ((g->>'global')::boolean OR (j."authorizationScopeKind" IN('dealer','location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."dealerIds") d WHERE NOT (g->'dealerIds' ? d)) AND (j."authorizationScopeKind"='dealer' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(j."locationIds") l WHERE NOT (g->'locationIds' ? l)))));END $fn$;

CREATE FUNCTION public.p07_api_lock_media_job_v1(session_token_hash text,expected_actor_id text,asset_id uuid,job_id uuid)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$ DECLARE j public.async_jobs%ROWTYPE;BEGIN PERFORM public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);SELECT * INTO j FROM public.async_jobs WHERE id=job_id AND "jobType"='media.process' AND payload->>'assetId'=asset_id::text FOR UPDATE;RETURN FOUND;END $fn$;

CREATE FUNCTION public.p07_api_retry_media_job_v1(session_token_hash text,expected_actor_id text,asset_id uuid,job_id uuid,expected_job_version integer,expected_retry_generation integer,next_binding jsonb,next_binding_revision integer,next_binding_hash text)
RETURNS SETOF public.async_jobs LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE context jsonb;read_g jsonb;manage_g jsonb;j public.async_jobs%ROWTYPE;asset public.media_assets%ROWTYPE;
BEGIN context:=public.p02_dashboard_authorization_context_v1(session_token_hash,expected_actor_id);read_g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='media.read');manage_g:=(SELECT value FROM jsonb_array_elements(context->'permissionGrants') value WHERE value->>'permissionKey'='media.manage_variants');IF read_g IS NULL OR manage_g IS NULL THEN RAISE EXCEPTION 'MEDIA_NOT_FOUND' USING ERRCODE='42501';END IF;
 SELECT * INTO asset FROM public.media_assets WHERE id=asset_id FOR UPDATE;SELECT * INTO j FROM public.async_jobs WHERE id=job_id FOR UPDATE;IF NOT FOUND OR asset.id IS NULL OR asset.status<>'processing' OR j."jobType"<>'media.process' OR j.status<>'failed' OR j.version<>expected_job_version OR j."retryGeneration"<>expected_retry_generation OR j."retryGeneration">=j."maxRetryGenerations" OR j."leaseOwner" IS NOT NULL OR j."leaseExpiresAt" IS NOT NULL OR j."attemptDeadline" IS NOT NULL OR j.payload->>'assetId'<>asset_id::text OR j."authorizationScopeKind"<>asset."authorizationScopeKind" OR j."dealerIds"<>asset."dealerIds" OR j."locationIds"<>asset."locationIds" OR next_binding_revision<>j."bindingRevision"+1 OR (next_binding->>'bindingRevision')::integer<>next_binding_revision OR (next_binding->>'retryGeneration')::integer<>j."retryGeneration"+1 OR next_binding_hash IS NULL THEN RAISE EXCEPTION 'MEDIA_VERSION_CONFLICT';END IF;
 UPDATE public.async_jobs SET status='queued',"retryGeneration"="retryGeneration"+1,"generationAttempt"=0,"nextRetryAt"=NULL,"finishedAt"=NULL,"failureClass"=NULL,"errorSummary"=NULL,"executionBinding"=next_binding,"bindingRevision"=next_binding_revision,"bindingHash"=next_binding_hash,version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=job_id RETURNING * INTO j;RETURN NEXT j;END $fn$;

ALTER FUNCTION public.p05_api_create_probe_v1(text,text,jsonb,text[],text) OWNER TO vanstro_p04_guard_owner;
ALTER FUNCTION public.p05_api_list_v1(text,text,text,text[],text[],timestamptz,timestamptz,integer,timestamptz,uuid,text[],text[],text,boolean,boolean) OWNER TO vanstro_p04_guard_owner;
ALTER FUNCTION public.p05_api_detail_v1(text,text,uuid) OWNER TO vanstro_p04_guard_owner;
ALTER FUNCTION public.p05_api_artifacts_v1(text,text,uuid) OWNER TO vanstro_p04_guard_owner;
